<!--vbase-->
<template>
  <div id="app">
    <h1>Vue Prism Editor - v1</h1>

    <pre>{{ code }}</pre>
    <input type="checkbox" v-model="lineNumbers" /> Linenumbers
    <prism-editor
      class="my-editor height-300"
      v-model="code"
      :highlight="highlighter"
      :line-numbers="lineNumbers"
    ></prism-editor>

    <h1>Autosize</h1>
    <p>
      don't use
      <b>min-height</b> or <b>height</b> you could still define
      <b>max-height</b>
    </p>
    <prism-editor
      class="my-editor"
      v-model="code"
      :highlight="highlighter"
    ></prism-editor>

    <div style="margin-top: 25px; font-size: 25px">
      Documantation on
      <a target="_blank" href="https://github.com/koca/vue-prism-editor"
        >Github</a
      >
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDocScriptStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { PrismEditor } from 'vue-prism-editor';
import 'vue-prism-editor/dist/prismeditor.min.css'; // import the styles somewhere

// import highlighting library (you can use any library you want just return html string)

import { highlight, languages } from 'src/utils/prism';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
    props: {},
  components: {
    PrismEditor,
  },
  watch: {
    selected_doc_type: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
  },
  data() {
    return {
      code: `
# This is an Example Code
def median(pool):
    copy = sorted(pool)
    size = len(copy)
    if size % 2 == 1:
        return copy[(size - 1) / 2]
    else:
        return (copy[size/2 - 1] + copy[size/2]) / 2
if __name__ == '__main__':
    import doctest
    doctest.testmod()
      `,
      lineNumbers: true,
    };
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    highlighter(code: any) {

      return highlight(code, languages.python, 'python'); // languages.<insert language> to return html with markup
    },    async initView() {
      try {
        this.selected_doc_type = String(this.$route.query.type);
        if (!this.selected_doc_type) {
          return;
        }
        this.setEmptyModel();
        this.processing = true;
        await this.getScript();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    async saveRecord() {
      try {
        this.processing = true;
        await this.saveCurrentModel();
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
  setup() {
    const doc_script = useDocScriptStore();
    const { getScript, saveCurrentModel, setEmptyModel } = doc_script;
    const {
      current_model,
      selected_doc_type,
      display_output_view,
      script_output,
      processing,
    } = storeToRefs(doc_script);

    return {
      script_output,
      display_output_view,
      selected_doc_type,
      saveCurrentModel,
      getScript,
      setEmptyModel,
      current_model,
      processing,
      CalHeight: ref('600'),
    };
  },
});
</script>

